generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       (SUM(xsd:decimal(?netCashFlow)) AS ?totalNetCashFlow)
       (AVG(xsd:decimal(?goalProgress)) AS ?avgGoalProgress)
       (SUM(xsd:decimal(?holdingGain)) AS ?totalHoldingGain)
       (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
       (AVG(xsd:decimal(?allocationPct)) AS ?avgAllocationPct)
WHERE {
  ?inv a wm:Investor ;
       wm:timeHorizon ?timeHorizon .

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?netCashFlow) WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amount .
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?progressPct)) AS ?goalProgress) WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:progressPct ?progressPct .
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?gain)) AS ?holdingGain) WHERE {
      ?hold a wm:PortfolioHolding ;
            wm:heldByInvestor ?inv ;
            wm:currentValue ?cv ;
            wm:cost ?cost .
      BIND ((xsd:decimal(?cv) - xsd:decimal(?cost)) AS ?gain)
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (MAX(xsd:decimal(?riskScore)) AS ?riskScore) WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:healthOfInvestor ?inv ;
          wm:riskScore ?riskScore .
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?allocationPct)) AS ?allocationPct) WHERE {
      ?alloc a wm:SectorAllocation ;
             wm:allocationOfInvestor ?inv ;
             wm:allocationPct ?allocationPct .
    } GROUP BY ?inv
  }
}
GROUP BY ?timeHorizon
ORDER BY ?timeHorizon

